package com.governai.decision;
import com.governai.audit.*;
import com.governai.exception.*;
import com.governai.organization.OrganizationRepository;
import com.governai.policy.PolicySectionRepository;
import com.governai.regulatory.RegulatorySectionRepository;
import com.governai.user.AppUserRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
@Service public class DecisionService {
 private final DecisionRequestRepository decisions; private final RetrievedEvidenceRepository evidence; private final AiRecommendationRepository recommendations; private final ApprovalRepository approvals; private final AuditService auditService; private final OrganizationRepository organizations; private final AppUserRepository users; private final PolicySectionRepository policySections; private final RegulatorySectionRepository regulatorySections;
 public DecisionService(DecisionRequestRepository decisions,RetrievedEvidenceRepository evidence,AiRecommendationRepository recommendations,ApprovalRepository approvals,AuditService auditService,OrganizationRepository organizations,AppUserRepository users,PolicySectionRepository policySections,RegulatorySectionRepository regulatorySections){this.decisions=decisions;this.evidence=evidence;this.recommendations=recommendations;this.approvals=approvals;this.auditService=auditService;this.organizations=organizations;this.users=users;this.policySections=policySections;this.regulatorySections=regulatorySections;}
 @Transactional public DecisionRequestResponse create(DecisionRequestPayload p){DecisionRequest d=new DecisionRequest();apply(d,p);d=decisions.save(d);audit(d,null,"DECISION_CREATED","DecisionRequest",d.getId());return DecisionRequestResponse.from(d);}
 @Transactional(readOnly=true) public DecisionRequestResponse get(UUID id){return DecisionRequestResponse.from(decision(id));}
 @Transactional(readOnly=true) public List<DecisionRequestResponse> list(UUID org,DecisionStatus status){List<DecisionRequest> result=status!=null?decisions.findByStatusOrderByCreatedAtDesc(status):org!=null?decisions.findByOrganizationIdOrderByCreatedAtDesc(org):decisions.findAll();return result.stream().map(DecisionRequestResponse::from).toList();}
 @Transactional public DecisionRequestResponse update(UUID id,DecisionRequestPayload p){DecisionRequest d=decision(id);apply(d,p);return DecisionRequestResponse.from(decisions.save(d));}
 @Transactional public DecisionRequestResponse updateStatus(UUID id,DecisionStatus requested){DecisionRequest d=decision(id);DecisionStatus prior=d.getStatus();if(!canTransition(prior,requested))throw new IllegalArgumentException("Cannot transition a decision from "+prior+" to "+requested);d.setStatus(requested);d=decisions.save(d);audit(d,null,"STATUS_CHANGED","DecisionRequest",d.getId());return DecisionRequestResponse.from(d);}
 @Transactional public void delete(UUID id){decisions.delete(decision(id));}
 @Transactional public EvidenceResponse addEvidence(UUID decisionId,EvidencePayload p){DecisionRequest d=decision(decisionId);if((p.policySectionId()==null)==(p.regulatorySectionId()==null))throw new IllegalArgumentException("Provide exactly one policySectionId or regulatorySectionId");if(p.policySectionId()!=null&&!policySections.existsById(p.policySectionId()))throw new ResourceNotFoundException("Policy section",p.policySectionId());if(p.regulatorySectionId()!=null&&!regulatorySections.existsById(p.regulatorySectionId()))throw new ResourceNotFoundException("Regulatory section",p.regulatorySectionId());RetrievedEvidence e=new RetrievedEvidence();e.setDecisionRequestId(decisionId);e.setSourceType(p.sourceType());e.setPolicySectionId(p.policySectionId());e.setRegulatorySectionId(p.regulatorySectionId());e.setSourceTitle(p.sourceTitle());e.setSectionReference(p.sectionReference());e.setEvidenceText(p.evidenceText());e.setRelevanceScore(p.relevanceScore());e.setEvidenceType(p.evidenceType());e=evidence.save(e);audit(d,null,"EVIDENCE_ADDED","RetrievedEvidence",e.getId());return EvidenceResponse.from(e);}
 @Transactional(readOnly=true) public List<EvidenceResponse> evidence(UUID id){decision(id);return evidence.findByDecisionRequestIdOrderByCreatedAtAsc(id).stream().map(this::evidenceResponse).toList();}
 @Transactional public RecommendationResponse addRecommendation(UUID decisionId,RecommendationPayload p){DecisionRequest d=decision(decisionId);AiRecommendation r=new AiRecommendation();r.setDecisionRequestId(decisionId);r.setRecommendation(p.recommendation());r.setExplanation(p.explanation());r.setIdentifiedRiskLevel(p.identifiedRiskLevel());r.setConfidenceScore(p.confidenceScore());r.setModelProvider(p.modelProvider());r.setModelName(p.modelName());r.setModelVersion(p.modelVersion());r.setPromptVersion(p.promptVersion());r.setMetadata(p.metadata());r=recommendations.save(r);if(d.getStatus()==DecisionStatus.DRAFT||d.getStatus()==DecisionStatus.ANALYZING){d.setStatus(d.isHumanReviewRequired()?DecisionStatus.PENDING_REVIEW:DecisionStatus.APPROVED);decisions.save(d);}audit(d,null,"RECOMMENDATION_GENERATED","AiRecommendation",r.getId());return RecommendationResponse.from(r);}
 @Transactional(readOnly=true) public List<RecommendationResponse> recommendations(UUID id){decision(id);return recommendations.findByDecisionRequestIdOrderByGeneratedAtAsc(id).stream().map(RecommendationResponse::from).toList();}
 @Transactional public ApprovalResponse approve(UUID decisionId,ApprovalPayload p){DecisionRequest d=decision(decisionId);if(!users.existsById(p.reviewerId()))throw new ResourceNotFoundException("User",p.reviewerId());if(d.getStatus()!=DecisionStatus.PENDING_REVIEW&&d.getStatus()!=DecisionStatus.ESCALATED)throw new IllegalArgumentException("Only pending or escalated decisions can be reviewed");Approval a=new Approval();a.setDecisionRequestId(decisionId);a.setReviewerId(p.reviewerId());a.setAction(p.action());a.setOriginalRecommendation(p.originalRecommendation());a.setFinalDecision(p.finalDecision());a.setReviewerComment(p.reviewerComment());a=approvals.save(a);d.setStatus(switch(p.action()){case APPROVE->DecisionStatus.APPROVED;case EDIT->DecisionStatus.CONDITIONALLY_APPROVED;case REJECT->DecisionStatus.REJECTED;case ESCALATE->DecisionStatus.ESCALATED;});decisions.save(d);audit(d,p.reviewerId(),"DECISION_"+p.action(),"Approval",a.getId());return ApprovalResponse.from(a);}
 @Transactional(readOnly=true) public List<ApprovalResponse> approvals(UUID id){decision(id);return approvals.findByDecisionRequestIdOrderByReviewedAtAsc(id).stream().map(ApprovalResponse::from).toList();}
 private DecisionRequest decision(UUID id){return decisions.findById(id).orElseThrow(()->new ResourceNotFoundException("Decision request",id));}
 private EvidenceResponse evidenceResponse(RetrievedEvidence item){if(item.getPolicySectionId()!=null){var section=policySections.findById(item.getPolicySectionId()).orElse(null);if(section!=null){var document=section.getPolicyDocument();return EvidenceResponse.withProvenance(item,document.getId(),document.getTitle(),section.getSectionNumber(),section.getHeading());}}if(item.getRegulatorySectionId()!=null){var section=regulatorySections.findById(item.getRegulatorySectionId()).orElse(null);if(section!=null){var document=section.getRegulatoryDocument();return EvidenceResponse.withProvenance(item,document.getId(),document.getTitle(),section.getSectionNumber(),section.getHeading());}}return EvidenceResponse.from(item);}
 private void apply(DecisionRequest d,DecisionRequestPayload p){if(p.organizationId()!=null&&!organizations.existsById(p.organizationId()))throw new OrganizationNotFoundException(p.organizationId());if(p.requestedBy()!=null&&!users.existsById(p.requestedBy()))throw new ResourceNotFoundException("User",p.requestedBy());if(p.assignedReviewer()!=null&&!users.existsById(p.assignedReviewer()))throw new ResourceNotFoundException("User",p.assignedReviewer());d.setOrganizationId(p.organizationId());d.setRequestedBy(p.requestedBy());d.setQuestion(p.question());d.setPurpose(p.purpose());d.setProvider(p.provider());d.setDataType(p.dataType());d.setAdditionalContext(p.additionalContext());d.setJurisdiction(p.jurisdiction());d.setRiskLevel(p.riskLevel());d.setHumanReviewRequired(Boolean.TRUE.equals(p.humanReviewRequired()));d.setAssignedReviewer(p.assignedReviewer());}
 private boolean canTransition(DecisionStatus from,DecisionStatus to){if(from==to)return true;return switch(from){case DRAFT->to==DecisionStatus.ANALYZING||to==DecisionStatus.PENDING_REVIEW||to==DecisionStatus.CLOSED;case ANALYZING->to==DecisionStatus.PENDING_REVIEW||to==DecisionStatus.APPROVED||to==DecisionStatus.CLOSED;case PENDING_REVIEW->to==DecisionStatus.APPROVED||to==DecisionStatus.CONDITIONALLY_APPROVED||to==DecisionStatus.REJECTED||to==DecisionStatus.ESCALATED;case ESCALATED->to==DecisionStatus.PENDING_REVIEW||to==DecisionStatus.APPROVED||to==DecisionStatus.REJECTED;case APPROVED,CONDITIONALLY_APPROVED,REJECTED->to==DecisionStatus.CLOSED;case CLOSED->false;};}
 private void audit(DecisionRequest d,UUID actor,String type,String entity,UUID entityId){auditService.record(d.getOrganizationId(),d.getId(),actor,type,entity,entityId);}
}
